func TestTmpScheme(t *testing.T) {
	tests := []struct {
		name string
		c    Context
		s    string
	}{
		{
			name: "TLS",
			c: &context{
				request: &http.Request{
					TLS: &tls.ConnectionState{},
				},
			},
			s: "https",
		},
		{
			name: "X-Forwarded-Proto https",
			c: &context{
				request: &http.Request{
					Header: http.Header{HeaderXForwardedProto: []string{"https"}},
				},
			},
			s: "https",
		},
		{
			name: "invalid X-Forwarded-Proto and uses X-Forwarded-Protocol",
			c: &context{
				request: &http.Request{
					Header: http.Header{
						HeaderXForwardedProto:    []string{"invalid"},
						HeaderXForwardedProtocol: []string{"https"},
					},
				},
			},
			s: "https",
		},
		{
			name: "ignores invalid forwarded headers and falls back to http",
			c: &context{
				request: &http.Request{
					Header: http.Header{
						HeaderXForwardedProto:     []string{"invalid"},
						HeaderXForwardedProtocol:  []string{"invalid"},
						HeaderXForwardedSsl:       []string{"invalid"},
						HeaderXUrlScheme:          []string{"invalid"},
					},
				},
			},
			s: "http",
		},
		{
			name: "invalid X-Forwarded-Proto and X-Forwarded-Ssl on",
			c: &context{
				request: &http.Request{
					Header: http.Header{
						HeaderXForwardedProto: []string{"invalid"},
						HeaderXForwardedSsl:   []string{"on"},
					},
				},
			},
			s: "https",
		},
		{
			name: "X-Forwarded-Protocol http",
			c: &context{
				request: &http.Request{
					Header: http.Header{HeaderXForwardedProtocol: []string{"http"}},
				},
			},
			s: "http",
		},
		{
			name: "X-Url-Scheme https",
			c: &context{
				request: &http.Request{
					Header: http.Header{HeaderXUrlScheme: []string{"https"}},
				},
			},
			s: "https",
		},
	}

	for _, tt := range tests {
		assert.Equal(t, tt.s, tt.c.Scheme(), tt.name)
	}
}

